const VERSION = '2.7.3-20261122';
const TAG = '[Spotify歌词]';
const STORE = {
  cache: 'SpotifyLyricsEnhanced.cache',
  log: 'SpotifyLyricsEnhanced.log',
  mxm: 'SpotifyLyricsEnhanced.mxmToken',
  scroll: 'SpotifyLyricsEnhanced.scroll',
  tpl: 'SpotifyLyricsEnhanced.template',
};
const SCORE_ACCEPT = 75;   // 低于该分数视为不可靠，不使用
const SCORE_STRONG = 115;  // 强匹配：歌名+歌手+时长+逐行同步 全部对上
const MOBILE_BUDGET = 4000; // 移动端 color-lyrics 最长检索时间（客户端等不了太久，超时后不重试）
const MOBILE_BUDGET_WITH_ORIGINAL = 1500; // 移动端且 Spotify 有原词：超过这个时间就先用原词

// ---------------------------------------------------------------- 配置
function parseArgs(raw) {
  if (raw && typeof raw === 'object') return raw;
  const out = {};
  for (const part of String(raw || '').split('&')) {
    const i = part.indexOf('=');
    if (i < 0) continue;
    const dec = s => { try { return decodeURIComponent(s); } catch { return s; } };
    out[dec(part.slice(0, i).trim())] = dec(part.slice(i + 1).trim());
  }
  return out;
}
function loadConfig(raw) {
  const a = parseArgs(raw);
  const unset = v => v == null || v === '' || /^\{\{\{.*\}\}\}$/.test(String(v));
  const bool = (v, d) => unset(v) ? d : !/^(false|0|no|off|否|关|关闭)$/i.test(String(v).trim());
  const num = (v, d, min, max) => { const n = Number(v); return unset(v) || !Number.isFinite(n) ? d : Math.min(max, Math.max(min, n)); };
  const all = ['qq', 'netease', 'kugou', 'kuwo', 'lrclib', 'musixmatch'];
  let sources = unset(a.sources) ? all : String(a.sources).toLowerCase().split(/[+,|\s]+/).filter(k => all.includes(k));
  if (!sources.length) sources = all;
  return {
    // 默认 false（同 v1）：外部源有可靠匹配就用 QQ/网易云等替换；找不到才保留 Spotify 原词
    preferOriginal: bool(a.prefer_original, false),
    translation: bool(a.translation, true),
    romanization: /^(all|全部|所有)$/i.test(String(a.romanization || '').trim()) ? 'all' : bool(a.romanization, true) ? 'dialect' : false,
    budget: num(a.budget, 6500, 2000, 12000),
    prefetchBudget: num(a.prefetch_budget, 4000, 0, 8000),
    cacheMinutes: num(a.cache_minutes, 30, 0, 1440),
    sources,
    convert: bool(a.convert, true),
    transStyle: /^(inline|换行|同字号|大字)$/i.test(String(a.trans_style || '').trim()) ? 'inline' : 'small',
    debug: /^(debug|verbose|详细|调试)$/i.test(String(a.log_level || '').trim()),
  };
}

// ---------------------------------------------------------------- 日志
function createLogger(cfg, scope) {
  const rid = Date.now().toString(36).slice(-5) + Math.random().toString(36).slice(2, 4);
  const prefix = TAG + '[' + scope + ' ' + rid + '] ';
  return {
    core: s => console.log(prefix + s),
    debug: s => { if (cfg.debug) console.log(prefix + '· ' + s); },
    child(extra) { const self = this; return { core: s => self.core(extra + s), debug: s => self.debug(extra + s), child: self.child.bind(self) }; },
  };
}
// 最近 40 条核心结果持久化，便于事后在 Surge 脚本编辑器/持久化数据里查看
function persistSummary(line) {
  try {
    if (typeof $persistentStore === 'undefined') return;
    const list = JSON.parse($persistentStore.read(STORE.log) || '[]');
    const d = new Date(Date.now() + 8 * 3600000).toISOString().replace('T', ' ').slice(5, 19);
    list.unshift(d + ' ' + line);
    $persistentStore.write(JSON.stringify(list.slice(0, 40)), STORE.log);
  } catch { /* 日志失败不影响主流程 */ }
}

// ---------------------------------------------------------------- 持久化（短期缓存：metadata 预取 → color-lyrics 复用）
const Store = {
  read(key) { try { const v = typeof $persistentStore !== 'undefined' ? $persistentStore.read(key) : null; return v ? JSON.parse(v) : null; } catch { return null; } },
  write(key, value) { try { if (typeof $persistentStore !== 'undefined') $persistentStore.write(JSON.stringify(value), key); } catch { /* ignore */ } },
};
function cacheGet(id, cfg) {
  if (!cfg.cacheMinutes) return null;
  const all = Store.read(STORE.cache) || {};
  const e = all[id];
  return e && e.exp > Date.now() && e.v === VERSION ? e : null; // 旧版本写入的缓存（可能含错误资料）一律不用
}
function cachePut(id, patch, cfg) {
  if (!cfg.cacheMinutes) return;
  const all = Store.read(STORE.cache) || {}, now = Date.now();
  for (const k of Object.keys(all)) if (!all[k] || all[k].exp < now) delete all[k];
  const prev = all[id] && all[id].v === VERSION ? all[id] : {};
  all[id] = { ...prev, ...patch, v: VERSION, exp: now + cfg.cacheMinutes * 60000, at: now };
  for (const k of Object.keys(all).sort((x, y) => all[y].at - all[x].at).slice(15)) delete all[k];
  Store.write(STORE.cache, all);
}

