    if (last > dur + 30000) return { reject: '时间轴超出歌曲' };
    if (last > dur + 12000) { score -= 25; notes.push('时间轴偏长'); }
    if (last < dur * 0.4) { score -= 10; notes.push('歌词疑似不完整'); }
