    for (const { c, m } of pick) ctx.log.debug(src.label + ' 候选「' + c.title + '」' + c.artists.join('/') + ' ' + (c.duration ? c.duration.toFixed(0) + 's' : '?') + ' 元数据分 ' + m.score);
