// ---------------------------------------------------------------- 曲目资料
async function fetchEmbedTrack(id, log, transport = httpTransport) {
  const t0 = Date.now();
  const r = await withDeadline(transport({ url: 'https://open.spotify.com/embed/track/' + id, method: 'GET', headers: { Accept: 'text/html', 'User-Agent': UA }, timeout: 4 }), 3500, '歌曲资料');
  if (Number(r.statusCode ?? r.status) !== 200) throw Error('歌曲资料 HTTP ' + (r.statusCode ?? r.status));
  const m = String(r.body || '').match(/<script\b[^>]*\bid=["']__NEXT_DATA__["'][^>]*>([\s\S]*?)<\/script>/i);
  if (!m) throw Error('歌曲页面缺少资料');
  const e = JSON.parse(m[1])?.props?.pageProps?.state?.data?.entity;
  if (e?.id !== id && e?.uri !== 'spotify:track:' + id) throw Error('歌曲资料 ID 不符');
  const artists = (e.artists || []).map(a => a.name).filter(Boolean);
  if (!(e.name || e.title) || !artists.length) throw Error('歌曲页面缺少歌名/歌手');
  log.debug('embed 资料 ' + (Date.now() - t0) + 'ms');
  return { id, track: e.name || e.title, artist: artists[0], artists, album: '', duration_ms: Number(e.duration) || 0 };
}

