// 歌词语言（Spotify 响应字段 10）：中文按简繁区分；其它语言不确定时留空
function lyricsLanguage(lines) {
  const textual = lines.filter(l => identity(l[1]));
  if (!textual.length || textual.filter(l => isChineseLine(l[1])).length / textual.length < 0.5) return '';
  return convDirection(textual) === 't2s' ? 'zh-Hant' : 'zh-Hans';
}
// 用外部歌词构造 Spotify 歌词对象（原文与译文合并在同一行，播放页预览与歌词页都能显示）
function buildLyrics(material, cfg) {
  const best = material.best;
  const aux = computeAux(best.lines, best.synced, [best, ...(material.aux || [])], cfg, best.source);
  const dir = cfg.convert ? convDirection(best.lines) : null;
  const conv = dir ? { dir, rows: convertRows(best.lines, dir) } : null;
  const comp = composeAux(best.lines.length, aux, conv, cfg);
  const lines = best.lines.map(([t, w], i) => ({ startTimeMs: String(best.synced ? t : 0), words: comp.inline[i] ? w + '\n' + comp.inline[i] : w, syllables: [], endTimeMs: '0', transliteratedWords: '' }));
  const usedNote = Object.entries(aux.used).filter(([, u]) => u.label !== best.label).map(([k, u]) => (k === 'trans' ? '译' : '音') + '·' + u.label).join(' ');
  return {
    lyrics: {
      // provider 用 Spotify 认识的 MusixMatch：iOS 播放页「歌词」卡片对未知 provider 不显示（显示名仍是真实来源）
      syncType: best.synced ? 'LINE_SYNCED' : 'UNSYNCED', lines, provider: 'MusixMatch', providerLyricsId: best.id,
      providerDisplayName: best.label + (usedNote ? ' · ' + usedNote : '') + ' · 歌词增强', syncLyricsUri: '', isDenseTypeface: true,
      alternatives: comp.alt ? [{ language: comp.altLang, lines: comp.alt, isRtlLanguage: false }] : [], language: lyricsLanguage(best.lines), isRtlLanguage: false, capStatus: '', previewLines: lines.slice(0, 5), fullscreenAction: 0,
    },
    aux, comp, conv,
  };
}

// ---------------------------------------------------------------- 诊断：记录 color-lyrics Protobuf 的字段结构（不含歌词正文），对比 Spotify 原始响应与脚本构造的响应
// 结果写入持久化 SpotifyLyricsEnhanced.shape（各类最近 3 条）
function pbShape(bytes, depth) {
  let fields;
  try { fields = pbRead(bytes); } catch { return null; }
  const groups = [];
  for (const f of fields) {
    const last = groups[groups.length - 1];
    if (last && last.field === f.field && last.wire === f.wire) { last.n++; continue; }
    groups.push({ field: f.field, wire: f.wire, n: 1, f });
  }
  return groups.map(g => {
    let d = g.field + (g.wire === 0 ? '=' + g.f.value : g.wire === 2 ? ':L' + g.f.value.length : ':W' + g.wire) + (g.n > 1 ? '×' + g.n : '');
    if (g.wire === 2 && depth > 0 && !(depth === 2 && g.field === 2) ) {
      const sub = pbShape(g.f.value, depth - 1);
      const txt = utf8(g.f.value);
      if (sub && sub.length && !/^[\x20-\x7e]{1,64}$/.test(txt)) d += '{' + sub + '}';
      else if (/^[\x20-\x7e]{1,64}$/.test(txt)) d += '"' + txt + '"';
    } else if (g.wire === 2 && depth === 2 && g.field === 2) {
      const sub = pbShape(g.f.value, 0); d += sub ? '{' + sub + '}' : '';
    }
    return d;
  }).join(',');
}
function recordShape(kind, id, bytes, depth = 3) {
  try {
    if (typeof $persistentStore === 'undefined') return;
    const key = 'SpotifyLyricsEnhanced.shape';
    const all = JSON.parse($persistentStore.read(key) || '{}');
    const list = (all[kind] || []).filter(x => x.id !== id);
    list.unshift({ id, at: new Date().toISOString().slice(11, 19), shape: pbShape(bytes, depth) });
    all[kind] = list.slice(0, 3);
    $persistentStore.write(JSON.stringify(all), key);
  } catch { /* 诊断失败不影响主流程 */ }
}

// ---------------------------------------------------------------- Spotify 响应模板（Protobuf）
// 歌词字段：1=同步类型 2=歌词行 9=译文(alternatives) 17=预览行；其余（3/4/5 提供方与 ID、8、10 语言、14、19…）保留
