  if (!textual.length) return { fields, dialect: null, conv: null };
  const chinese = textual.filter(l => isChineseLine(l[1])).length / textual.length;
  if (cfg.translation && 1 - chinese >= 0.3) fields.push('trans');
  let dialect = chinese >= 0.3 ? detectDialect(textual) : null;
  if (!dialect && chinese >= 0.3 && versionTags(track?.track).has('cantonese')) dialect = { key: 'cantonese', label: '粤语', n: 0, byTitle: true };
